package com.rikkeibank.customer.service; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import com.rikkeibank.customer.model.Customer; import com.rikkeibank.customer.repository.CustomerRepository; import java.util.Optional; import org.junit.jupiter.api.*;
class CustomerServiceTest{CustomerRepository repo=mock(CustomerRepository.class);CustomerService service=new CustomerService(repo);@Test void findByIdReturnsCustomer(){Customer c=new Customer();c.setId(1L);when(repo.findById(1L)).thenReturn(Optional.of(c));assertEquals(1L,service.findById(1L).getId());verify(repo).findById(1L);}}
